static void on_process(void* userdata) {
  struct pw_stream* s = (struct pw_stream*)userdata;
  g_process_count++;
  struct pw_buffer* b = pw_stream_dequeue_buffer(s);
  if (!b) {
    return;
  }
  struct spa_buffer* buf = b->buffer;
  if (!buf || buf->n_datas == 0 || buf->datas[0].data == nullptr ||
      buf->datas[0].chunk == nullptr) {
    pw_stream_queue_buffer(s, b);
    return;
  }
  const uint32_t size = buf->datas[0].chunk->size;
  if (size == 0) {
    g_empty_buffers++;
  } else {
    g_samples_count += size / sizeof(int16_t);
  }
  pw_stream_queue_buffer(s, b);
}

static void on_param_changed(void* userdata, uint32_t id, const struct spa_pod* param) {
  if (param == nullptr || id != SPA_PARAM_Format) {
    return;
  }
  struct spa_audio_info_raw info;
  if (spa_format_audio_raw_parse(param, &info) < 0) {
    return;
  }
  printf("vinput: negotiated format: rate=%u channels=%u fmt=%d position[0]=%u flags=%u\n",
         info.rate, info.channels, info.format, info.position[0], info.flags);
}

static void on_state_changed(void* userdata, enum pw_stream_state old,
                             enum pw_stream_state state, const char* error) {
  printf("vinput: stream state: %s -> %s%s%s\n",
         pw_stream_state_as_string(old), pw_stream_state_as_string(state),
         error ? " error=" : "", error ? error : "");
}

int main(int argc, char* argv[]) {
  bool fix_channel_position = false;
  bool start_inactive = true;

  for (int i = 1; i < argc; ++i) {
    if (strcmp(argv[i], "--fix-position") == 0) {
      fix_channel_position = true;
    }
    if (strcmp(argv[i], "--start-active") == 0) {
      start_inactive = false;
    }
  }

  printf("Running test: fix_position=%s start_inactive=%s\n",
         fix_channel_position ? "true" : "false",
         start_inactive ? "true" : "false");

  pw_init(nullptr, nullptr);
  struct pw_thread_loop* loop = pw_thread_loop_new("test-loop", nullptr);
  pw_thread_loop_start(loop);

  pw_thread_loop_lock(loop);

  struct pw_stream_events stream_events{};
  stream_events.version = PW_VERSION_STREAM_EVENTS;
  stream_events.param_changed = on_param_changed;
  stream_events.process = on_process;
  stream_events.state_changed = on_state_changed;

  auto* properties = pw_properties_new(
      PW_KEY_MEDIA_TYPE, "Audio",
      PW_KEY_MEDIA_CATEGORY, "Capture",
      PW_KEY_MEDIA_ROLE, "Communication",
      PW_KEY_STREAM_CAPTURE_SINK, "false",
      nullptr);

  struct pw_stream* stream = pw_stream_new_simple(
      pw_thread_loop_get_loop(loop), "vinput-capture", properties,
      &stream_events, nullptr);

  // Set userdata pointer to stream for on_process
  // Since pw_stream_new_simple took userdata before stream was created, we can recreate or pass userdata
  pw_stream_destroy(stream);
  stream = pw_stream_new_simple(
      pw_thread_loop_get_loop(loop), "vinput-capture",
      pw_properties_new(
          PW_KEY_MEDIA_TYPE, "Audio",
          PW_KEY_MEDIA_CATEGORY, "Capture",
          PW_KEY_MEDIA_ROLE, "Communication",
          PW_KEY_STREAM_CAPTURE_SINK, "false",
          nullptr),
      &stream_events, nullptr);

  uint8_t pod_buffer[1024];
  struct spa_pod_builder builder = SPA_POD_BUILDER_INIT(pod_buffer, sizeof(pod_buffer));
  struct spa_audio_info_raw raw_info{};
  raw_info.format = SPA_AUDIO_FORMAT_S16_LE;
  raw_info.rate = 16000;
  raw_info.channels = 1;
  if (fix_channel_position) {
    raw_info.position[0] = SPA_AUDIO_CHANNEL_MONO;
  }

  const struct spa_pod* params[1];
  params[0] = spa_format_audio_raw_build(&builder, SPA_PARAM_EnumFormat, &raw_info);

  int flags = PW_STREAM_FLAG_AUTOCONNECT | PW_STREAM_FLAG_MAP_BUFFERS;
  if (start_inactive) {
    flags |= PW_STREAM_FLAG_INACTIVE;
  }

  int ret = pw_stream_connect(stream, PW_DIRECTION_INPUT, PW_ID_ANY,
                              static_cast<pw_stream_flags>(flags), params, 1);
  if (ret < 0) {
    printf("pw_stream_connect failed: %d\n", ret);
    pw_thread_loop_unlock(loop);
    return 1;
  }

  // Update userdata in stream
  // (we can just use a global or pass it properly)
  pw_thread_loop_unlock(loop);

  if (start_inactive) {
    // Wait briefly then activate, like AudioCapture does in BeginRecording
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    pw_thread_loop_lock(loop);
    pw_stream_set_active(stream, true);
    pw_thread_loop_unlock(loop);
  }

  // Record for 2 seconds
  std::this_thread::sleep_for(std::chrono::seconds(2));

  pw_thread_loop_lock(loop);
  pw_stream_destroy(stream);
  pw_thread_loop_unlock(loop);

  pw_thread_loop_stop(loop);
  pw_thread_loop_destroy(loop);
  pw_deinit();

  printf("RESULTS: process_calls=%d, samples_received=%d, empty_buffers=%d\n",
         g_process_count.load(), g_samples_count.load(), g_empty_buffers.load());
  return 0;
}

