#include <pipewire/pipewire.h>
#include <pipewire/stream.h>
#include <spa/param/audio/format-utils.h>
#include <spa/param/audio/raw.h>
#include <spa/pod/builder.h>

#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <thread>

static std::atomic<int> g_process_count{0};
static std::atomic<int> g_samples_count{0};
static std::atomic<int> g_empty_count{0};
static struct pw_stream* g_stream = nullptr;

static void on_process(void* userdata) {
  (void)userdata;
  struct pw_stream* s = g_stream;
  if (s == nullptr) {
    return;
  }
  g_process_count++;
  struct pw_buffer* b = pw_stream_dequeue_buffer(s);
  if (b == nullptr) {
    return;
  }
  struct spa_buffer* buf = b->buffer;
  if (buf != nullptr && buf->n_datas > 0 && buf->datas[0].data != nullptr &&
      buf->datas[0].chunk != nullptr) {
    const uint32_t size = buf->datas[0].chunk->size;
    if (size == 0) {
      g_empty_count++;
    } else {
      g_samples_count += static_cast<int>(size / sizeof(int16_t));
    }
  }
  pw_stream_queue_buffer(s, b);
}

static void on_param_changed(void* userdata, uint32_t id, const struct spa_pod* param) {
  (void)userdata;
  if (param == nullptr || id != SPA_PARAM_Format) {
    return;
  }
  struct spa_audio_info_raw info {};
  if (spa_format_audio_raw_parse(param, &info) < 0) {
    return;
  }
  printf("[test] negotiated format: rate=%u channels=%u fmt=%d position[0]=%u flags=%u\n",
         info.rate, info.channels, info.format, info.channels > 0 ? info.position[0] : 0,
         info.flags);
}

static void on_state_changed(void* userdata, enum pw_stream_state old,
                             enum pw_stream_state state, const char* error) {
  (void)userdata;
  const char* err_str = (error != nullptr && error[0] != '\0') ? error : nullptr;
  printf("[test] stream state: %s -> %s%s%s\n", pw_stream_state_as_string(old),
         pw_stream_state_as_string(state), err_str != nullptr ? " error=" : "",
         err_str != nullptr ? err_str : "");
}

int main(int argc, char* argv[]) {
  bool set_mono_position = false;
  bool start_inactive = true;
  int duration_ms = 2000;
  const char* role = "Communication";

  for (int i = 1; i < argc; ++i) {
    if (strcmp(argv[i], "--mono") == 0) {
      set_mono_position = true;
    } else if (strcmp(argv[i], "--unknown") == 0) {
      set_mono_position = false;
    } else if (strcmp(argv[i], "--start-active") == 0) {
      start_inactive = false;
    } else if (strcmp(argv[i], "--start-inactive") == 0) {
      start_inactive = true;
    } else if (strcmp(argv[i], "--role") == 0 && i + 1 < argc) {
      role = argv[++i];
    } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
      duration_ms = atoi(argv[++i]);
    }
  }

  printf("[test] config: position=%s, start_inactive=%s, role=%s, duration=%dms\n",
         set_mono_position ? "SPA_AUDIO_CHANNEL_MONO" : "SPA_AUDIO_CHANNEL_UNKNOWN",
         start_inactive ? "true" : "false", role, duration_ms);

  pw_init(nullptr, nullptr);
  struct pw_thread_loop* loop = pw_thread_loop_new("test-loop", nullptr);
  if (loop == nullptr) {
    fprintf(stderr, "[test] failed to create thread loop\n");
    return 1;
  }
  pw_thread_loop_start(loop);

  pw_thread_loop_lock(loop);

  struct pw_stream_events stream_events {};
  stream_events.version = PW_VERSION_STREAM_EVENTS;
  stream_events.param_changed = on_param_changed;
  stream_events.process = on_process;
  stream_events.state_changed = on_state_changed;

  struct pw_properties* properties = pw_properties_new(
      PW_KEY_MEDIA_TYPE, "Audio", PW_KEY_MEDIA_CATEGORY, "Capture", PW_KEY_MEDIA_ROLE, role,
      PW_KEY_STREAM_CAPTURE_SINK, "false", nullptr);

  struct pw_stream* stream = pw_stream_new_simple(
      pw_thread_loop_get_loop(loop), "vinput-capture-test", properties, &stream_events, nullptr);
  if (stream == nullptr) {
    fprintf(stderr, "[test] failed to create stream\n");
    pw_thread_loop_unlock(loop);
    return 1;
  }
  g_stream = stream;

  uint8_t pod_buffer[1024];
  struct spa_pod_builder builder = SPA_POD_BUILDER_INIT(pod_buffer, sizeof(pod_buffer));
  struct spa_audio_info_raw raw_info {};
  raw_info.format = SPA_AUDIO_FORMAT_S16_LE;
  raw_info.rate = 16000;
  raw_info.channels = 1;
  if (set_mono_position) {
    raw_info.position[0] = SPA_AUDIO_CHANNEL_MONO;
  }

  const struct spa_pod* params[1];
  params[0] = spa_format_audio_raw_build(&builder, SPA_PARAM_EnumFormat, &raw_info);

  int flags = PW_STREAM_FLAG_AUTOCONNECT | PW_STREAM_FLAG_MAP_BUFFERS;
  if (start_inactive) {
    flags |= PW_STREAM_FLAG_INACTIVE;
  }

  int ret = pw_stream_connect(stream, PW_DIRECTION_INPUT, PW_ID_ANY,
                              static_cast<pw_stream_flags>(flags), params, 1);
  if (ret < 0) {
    fprintf(stderr, "[test] pw_stream_connect failed: %d\n", ret);
    pw_thread_loop_unlock(loop);
    return 1;
  }

  pw_thread_loop_unlock(loop);

  if (start_inactive) {
    std::this_thread::sleep_for(std::chrono::milliseconds(50));
    pw_thread_loop_lock(loop);
    pw_stream_set_active(stream, true);
    pw_thread_loop_unlock(loop);
  }

  std::this_thread::sleep_for(std::chrono::milliseconds(duration_ms));

  pw_thread_loop_lock(loop);
  pw_stream_destroy(stream);
  g_stream = nullptr;
  pw_thread_loop_unlock(loop);

  pw_thread_loop_stop(loop);
  pw_thread_loop_destroy(loop);
  pw_deinit();

  printf("[test] SUMMARY: process_calls=%d, samples_received=%d, empty_buffers=%d\n",
         g_process_count.load(), g_samples_count.load(), g_empty_count.load());
  return 0;
}

