bool EnvTruthy(const char* value) {
  if (!value || value[0] == '\0') {
    return false;
  }
  return value[0] == '1' || value[0] == 't' || value[0] == 'T' || value[0] == 'y' ||
         value[0] == 'Y';
}

bool EnvFalsey(const char* value) {
  if (!value || value[0] == '\0') {
    return false;
  }
  return value[0] == '0' || value[0] == 'f' || value[0] == 'F' || value[0] == 'n' ||
         value[0] == 'N';
}

